#!/usr/bin/env node
/**
 * Spreadsheet evaluator: reads a sheet from stdin and prints values or dependencies.
 */

import { readFileSync } from 'fs'

// Parse and validate a cell address
function parseAddress(addr) {
  const match = addr.match(/^([A-Z]+)(\d+)$/)
  if (!match) return null

  const colStr = match[1]
  const rowStr = match[2]

  // Parse column (A-Z = 1-26, AA-ZZ = 27-52)
  let col = 0
  for (let i = 0; i < colStr.length; i++) {
    col = col * 26 + (colStr.charCodeAt(i) - 64)
  }

  const row = parseInt(rowStr)

  // Validate: columns A-Z (1-26) and AA-ZZ (27-52), rows 1-999
  if (col < 1 || col > 52 || row < 1 || row > 999) {
    return null
  }

  return { col, row, str: addr }
}

// Format a cell address for output
function formatAddress(col, row) {
  let colStr = ''
  if (col <= 26) {
    colStr = String.fromCharCode(64 + col)
  } else {
    colStr = String.fromCharCode(64 + Math.floor((col - 1) / 26)) +
             String.fromCharCode(64 + ((col - 1) % 26) + 1)
  }
  return colStr + row
}

// Tokenize a formula
function tokenize(formula) {
  const tokens = []
  let i = 0

  while (i < formula.length) {
    // Skip whitespace
    if (formula[i] === ' ' || formula[i] === '\t') {
      i++
      continue
    }

    // Numbers
    if (/\d/.test(formula[i])) {
      let num = ''
      while (i < formula.length && /[\d.]/.test(formula[i])) {
        num += formula[i]
        i++
      }
      tokens.push({ type: 'number', value: parseFloat(num) })
      continue
    }

    // Operators and punctuation
    if (formula[i] === '(') {
      tokens.push({ type: '(', value: '(' })
      i++
      continue
    }
    if (formula[i] === ')') {
      tokens.push({ type: ')', value: ')' })
      i++
      continue
    }
    if (formula[i] === ':') {
      tokens.push({ type: ':', value: ':' })
      i++
      continue
    }
    if (formula[i] === ',') {
      tokens.push({ type: ',', value: ',' })
      i++
      continue
    }

    // Multi-char operators
    if (i + 1 < formula.length) {
      const twoChar = formula.slice(i, i + 2)
      if (['<=', '<>', '>='].includes(twoChar)) {
        tokens.push({ type: 'op', value: twoChar })
        i += 2
        continue
      }
    }

    // Single char operators
    if ('+-*/<>=^'.includes(formula[i])) {
      tokens.push({ type: 'op', value: formula[i] })
      i++
      continue
    }

    // Names (identifiers: cell addresses, TRUE, FALSE, function names)
    if (/[A-Za-z]/.test(formula[i])) {
      let name = ''
      while (i < formula.length && /[A-Za-z0-9]/.test(formula[i])) {
        name += formula[i]
        i++
      }
      name = name.toUpperCase()

      if (name === 'TRUE') {
        tokens.push({ type: 'boolean', value: true })
      } else if (name === 'FALSE') {
        tokens.push({ type: 'boolean', value: false })
      } else if (/^[A-Z]+\d+$/.test(name)) {
        tokens.push({ type: 'address', value: name })
      } else {
        // It's a function name or invalid name
        tokens.push({ type: 'name', value: name })
      }
      continue
    }

    // Unknown character
    return null
  }

  return tokens
}

// Parser for formulas - recursive descent
class FormulaParser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null
  }

  consume() {
    return this.tokens[this.pos++]
  }

  parse() {
    if (!this.tokens || this.tokens.length === 0) return null
    const expr = this.parseComparison()
    if (this.pos !== this.tokens.length) return null // Unconsumed tokens
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (!left) return null

    while (this.peek() && this.peek().type === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(this.peek().value)) {
      const op = this.consume().value
      const right = this.parseAdditive()
      if (!right) return null
      left = { type: 'binop', op, left, right }
    }

    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (!left) return null

    while (this.peek() && this.peek().type === 'op' && ['+', '-'].includes(this.peek().value)) {
      const op = this.consume().value
      const right = this.parseMultiplicative()
      if (!right) return null
      left = { type: 'binop', op, left, right }
    }

    return left
  }

  parseMultiplicative() {
    let left = this.parseExponent()
    if (!left) return null

    while (this.peek() && this.peek().type === 'op' && ['*', '/', '%'].includes(this.peek().value)) {
      const op = this.consume().value
      const right = this.parseExponent()
      if (!right) return null
      left = { type: 'binop', op, left, right }
    }

    return left
  }

  parseExponent() {
    let base = this.parseUnary()
    if (!base) return null

    if (this.peek() && this.peek().type === 'op' && this.peek().value === '^') {
      const op = this.consume().value
      const exp = this.parseExponent() // Right associative
      if (!exp) return null
      return { type: 'binop', op, left: base, right: exp }
    }

    return base
  }

  parseUnary() {
    if (this.peek() && this.peek().type === 'op' && ['+', '-'].includes(this.peek().value)) {
      const op = this.consume().value
      const expr = this.parseUnary()
      if (!expr) return null
      return { type: 'unary', op, expr }
    }

    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.peek()
    if (!token) return null

    // Number
    if (token.type === 'number') {
      this.consume()
      return { type: 'number', value: token.value }
    }

    // Boolean
    if (token.type === 'boolean') {
      this.consume()
      return { type: 'boolean', value: token.value }
    }

    // Address or range
    if (token.type === 'address') {
      const addr = this.consume().value
      if (this.peek() && this.peek().type === ':') {
        // Range
        this.consume()
        const endToken = this.peek()
        if (!endToken || endToken.type !== 'address') return null
        const endAddr = this.consume().value
        return { type: 'range', start: addr, end: endAddr }
      }
      return { type: 'address', value: addr }
    }

    // Parentheses
    if (token.type === '(') {
      this.consume()
      const expr = this.parseComparison()
      if (!expr) return null
      if (!this.peek() || this.peek().type !== ')') return null
      this.consume()
      return expr
    }

    // Function call
    if (token.type === 'name') {
      const name = this.consume().value
      if (!this.peek() || this.peek().type !== '(') return null
      this.consume()

      const args = []
      if (this.peek() && this.peek().type !== ')') {
        while (true) {
          const arg = this.parseComparison()
          if (!arg) return null
          args.push(arg)
          if (!this.peek()) return null
          if (this.peek().type === ')') break
          if (this.peek().type !== ',') return null
          this.consume()
        }
      }

      if (!this.peek() || this.peek().type !== ')') return null
      this.consume()

      return { type: 'call', name, args }
    }

    return null
  }
}

// Value types
const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

function isError(val) {
  return typeof val === 'string' && ERROR_TOKENS.includes(val)
}

function formatValue(val) {
  if (isError(val)) return val
  if (typeof val === 'boolean') return val ? 'TRUE' : 'FALSE'
  if (typeof val === 'number') {
    // Round to 10 significant digits
    if (!isFinite(val)) return '#DIV/0!'
    return parseFloat(val.toPrecision(10)).toString()
  }
  return val
}

// Main Sheet class
class Sheet {
  constructor() {
    this.cells = new Map() // key: "col:row", value: { addr, content, value, formula }
    this.evaluated = new Set()
    this.evaluating = new Set()
  }

  addCell(col, row, addr, content, lineNum) {
    const key = `${col}:${row}`
    if (this.cells.has(key)) {
      throw { type: 'error', message: `error: line ${lineNum}: cell ${addr} is declared twice\n` }
    }

    // Parse content
    let value, formula = null
    if (content.startsWith('=')) {
      formula = content.slice(1)
      value = undefined // Will be evaluated on demand
    } else {
      value = this.parseLiteral(content)
    }

    this.cells.set(key, { col, row, addr, content, value, formula })
  }

  parseLiteral(content) {
    if (content === '') return 0

    // Check if it's a number
    if (/^-?\d+(\.\d+)?$/.test(content)) {
      return parseFloat(content)
    }

    // Check if it's an error token
    if (ERROR_TOKENS.includes(content)) {
      return content
    }

    // It's text
    return content
  }

  getCell(col, row) {
    const key = `${col}:${row}`
    if (!this.cells.has(key)) {
      return { col, row, addr: formatAddress(col, row), value: 0 }
    }
    return this.cells.get(key)
  }

  evaluateCell(col, row) {
    const key = `${col}:${row}`
    const cell = this.getCell(col, row)

    // Already evaluated
    if (this.evaluated.has(key)) {
      return cell.value
    }

    // Check for cycle
    if (this.evaluating.has(key)) {
      this.cells.set(key, { ...cell, value: '#CYCLE!' })
      return '#CYCLE!'
    }

    if (!cell.formula) {
      // Literal
      this.evaluated.add(key)
      return cell.value !== undefined ? cell.value : 0
    }

    // Evaluate formula
    this.evaluating.add(key)
    const tokens = tokenize(cell.formula)
    if (!tokens) {
      this.cells.set(key, { ...cell, value: '#ERR!' })
      this.evaluating.delete(key)
      this.evaluated.add(key)
      return '#ERR!'
    }

    const parser = new FormulaParser(tokens)
    const ast = parser.parse()
    if (!ast) {
      this.cells.set(key, { ...cell, value: '#ERR!' })
      this.evaluating.delete(key)
      this.evaluated.add(key)
      return '#ERR!'
    }

    const result = this.evaluateAST(ast)
    this.cells.set(key, { ...cell, value: result })
    this.evaluating.delete(key)
    this.evaluated.add(key)
    return result
  }

  evaluateAST(ast) {
    if (!ast) return '#ERR!'

    if (ast.type === 'number') {
      return ast.value
    }

    if (ast.type === 'boolean') {
      return ast.value
    }

    if (ast.type === 'address') {
      const addr = parseAddress(ast.value)
      if (!addr) {
        return '#REF!'
      }
      return this.evaluateCell(addr.col, addr.row)
    }

    if (ast.type === 'unary') {
      const expr = this.evaluateAST(ast.expr)
      if (isError(expr)) return expr
      const num = this.toNumber(expr)
      if (isError(num)) return num
      return ast.op === '-' ? -num : num
    }

    if (ast.type === 'binop') {
      const left = this.evaluateAST(ast.left)
      const right = this.evaluateAST(ast.right)

      // Error propagation: left wins
      if (isError(left)) return left
      if (isError(right)) return right

      // Comparison operators
      if (['=', '<>', '<', '<=', '>', '>='].includes(ast.op)) {
        return this.evaluateComparison(left, right, ast.op)
      }

      // Arithmetic operators
      const ln = this.toNumber(left)
      if (isError(ln)) return ln
      const rn = this.toNumber(right)
      if (isError(rn)) return rn

      switch (ast.op) {
        case '+': return ln + rn
        case '-': return ln - rn
        case '*': return ln * rn
        case '/': {
          if (rn === 0) return '#DIV/0!'
          const result = ln / rn
          if (!isFinite(result)) return '#DIV/0!'
          return result
        }
        case '^': return Math.pow(ln, rn)
        default: return '#ERR!'
      }
    }

    if (ast.type === 'range') {
      // Ranges are not allowed outside function arguments
      return '#ERR!'
    }

    if (ast.type === 'call') {
      return this.evaluateCall(ast.name, ast.args)
    }

    return '#ERR!'
  }

  evaluateComparison(left, right, op) {
    const typeOrder = (val) => {
      if (typeof val === 'number') return 0
      if (typeof val === 'string') return 1
      if (typeof val === 'boolean') return 2
      return 3
    }

    const leftType = typeOrder(left)
    const rightType = typeOrder(right)

    let cmp
    if (leftType === rightType) {
      if (typeof left === 'boolean') {
        cmp = left === right ? 0 : (left ? 1 : -1)
      } else {
        cmp = left < right ? -1 : (left > right ? 1 : 0)
      }
    } else {
      cmp = leftType < rightType ? -1 : 1
    }

    switch (op) {
      case '=': return cmp === 0
      case '<>': return cmp !== 0
      case '<': return cmp < 0
      case '<=': return cmp <= 0
      case '>': return cmp > 0
      case '>=': return cmp >= 0
      default: return '#ERR!'
    }
  }

  toNumber(val) {
    if (typeof val === 'number') return val
    if (typeof val === 'boolean') return val ? 1 : 0
    return '#VALUE!'
  }

  expandRange(ast) {
    if (ast.type === 'range') {
      const start = parseAddress(ast.start)
      const end = parseAddress(ast.end)
      if (!start || !end) return []

      const cells = []
      const minCol = Math.min(start.col, end.col)
      const maxCol = Math.max(start.col, end.col)
      const minRow = Math.min(start.row, end.row)
      const maxRow = Math.max(start.row, end.row)

      for (let col = minCol; col <= maxCol; col++) {
        for (let row = minRow; row <= maxRow; row++) {
          cells.push({ col, row })
        }
      }
      return cells
    }

    if (ast.type === 'address') {
      const addr = parseAddress(ast.value)
      if (!addr) return []
      return [{ col: addr.col, row: addr.row }]
    }

    return []
  }

  evaluateCall(name, args) {
    const validFunctions = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!validFunctions.includes(name)) {
      return '#NAME?'
    }

    if (name === 'IF') {
      if (args.length !== 3) return '#ERR!'
      const cond = this.evaluateAST(args[0])
      if (isError(cond)) return cond

      const condVal = typeof cond === 'boolean' ? cond : 
                      (typeof cond === 'number' ? cond !== 0 : false)

      if (condVal) {
        return this.evaluateAST(args[1])
      } else {
        return this.evaluateAST(args[2])
      }
    }

    if (name === 'ABS') {
      if (args.length !== 1) return '#ERR!'
      const val = this.evaluateAST(args[0])
      if (isError(val)) return val
      const num = this.toNumber(val)
      if (isError(num)) return num
      return Math.abs(num)
    }

    // For SUM, MIN, MAX, COUNT, AVG
    if (args.length < 1) return '#ERR!'

    const values = []
    for (const arg of args) {
      if (arg.type === 'range') {
        const cells = this.expandRange(arg)
        for (const { col, row } of cells) {
          const val = this.evaluateCell(col, row)
          values.push(val)
        }
      } else {
        const val = this.evaluateAST(arg)
        values.push(val)
      }
    }

    // Check for errors
    for (const val of values) {
      if (isError(val)) return val
    }

    if (name === 'COUNT') {
      let count = 0
      for (const val of values) {
        if (typeof val === 'number') count++
      }
      return count
    }

    // For SUM, MIN, MAX, AVG, convert all to numbers
    const numbers = []
    for (const val of values) {
      const num = this.toNumber(val)
      if (isError(num)) return num
      numbers.push(num)
    }

    if (name === 'SUM') {
      return numbers.reduce((a, b) => a + b, 0)
    }

    if (name === 'MIN') {
      return Math.min(...numbers)
    }

    if (name === 'MAX') {
      return Math.max(...numbers)
    }

    if (name === 'AVG') {
      if (numbers.length === 0) return 0
      return numbers.reduce((a, b) => a + b, 0) / numbers.length
    }

    return '#ERR!'
  }

  getCellDependencies(col, row) {
    const cell = this.getCell(col, row)
    if (!cell.formula) {
      return []
    }

    const tokens = tokenize(cell.formula)
    if (!tokens) return []

    const parser = new FormulaParser(tokens)
    const ast = parser.parse()
    if (!ast) return []

    const deps = new Set()
    this.collectDependencies(ast, deps)
    return Array.from(deps)
  }

  collectDependencies(ast, deps) {
    if (!ast) return

    if (ast.type === 'address') {
      const addr = parseAddress(ast.value)
      if (addr) {
        const key = `${addr.col}:${addr.row}`
        deps.add(key)
      }
      return
    }

    if (ast.type === 'range') {
      const start = parseAddress(ast.start)
      const end = parseAddress(ast.end)
      if (start && end) {
        const minCol = Math.min(start.col, end.col)
        const maxCol = Math.max(start.col, end.col)
        const minRow = Math.min(start.row, end.row)
        const maxRow = Math.max(start.row, end.row)

        for (let col = minCol; col <= maxCol; col++) {
          for (let row = minRow; row <= maxRow; row++) {
            const key = `${col}:${row}`
            deps.add(key)
          }
        }
      }
      return
    }

    if (ast.type === 'unary') {
      this.collectDependencies(ast.expr, deps)
      return
    }

    if (ast.type === 'binop') {
      this.collectDependencies(ast.left, deps)
      this.collectDependencies(ast.right, deps)
      return
    }

    if (ast.type === 'call') {
      for (const arg of ast.args) {
        this.collectDependencies(arg, deps)
      }
      return
    }
  }
}

// Main program
async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['values', 'deps'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read stdin
  let input = ''
  try {
    input = readFileSync(0, 'utf-8')
  } catch (e) {
    process.stderr.write('error: failed to read input\n')
    process.exit(2)
  }

  // Parse input
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const sheet = new Sheet()
  let lineNum = 0

  for (const line of lines) {
    lineNum++

    // Strip leading spaces/tabs
    let trimmed = line.replace(/^[ \t]+/, '')

    // Ignore empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }

    // Parse address and content
    const match = trimmed.match(/^(\S+)([ \t]+|$)/)
    if (!match) {
      continue
    }

    const addrStr = match[1]
    const rest = trimmed.slice(match[0].length)

    // Validate address
    const addr = parseAddress(addrStr.toUpperCase())
    if (!addr) {
      process.stderr.write(`error: line ${lineNum}: invalid cell address ${addrStr}\n`)
      process.exit(2)
    }

    // Add cell
    try {
      sheet.addCell(addr.col, addr.row, addr.str, rest, lineNum)
    } catch (e) {
      if (e.type === 'error') {
        process.stderr.write(e.message)
        process.exit(2)
      }
      throw e
    }
  }

  // Get all cells in order
  const cellArray = Array.from(sheet.cells.values())
  cellArray.sort((a, b) => {
    if (a.col !== b.col) return a.col - b.col
    return a.row - b.row
  })

  // Output
  if (mode === 'values') {
    for (const cell of cellArray) {
      const value = sheet.evaluateCell(cell.col, cell.row)
      const formatted = formatValue(value)
      process.stdout.write(`${cell.addr}=${formatted}\n`)
    }
  } else {
    for (const cell of cellArray) {
      const deps = sheet.getCellDependencies(cell.col, cell.row)
      deps.sort((a, b) => {
        const [aCol, aRow] = a.split(':').map(Number)
        const [bCol, bRow] = b.split(':').map(Number)
        if (aCol !== bCol) return aCol - bCol
        return aRow - bRow
      })

      const depAddrs = deps.map(key => {
        const [col, row] = key.split(':').map(Number)
        return formatAddress(col, row)
      })

      if (depAddrs.length === 0) {
        process.stdout.write(`${cell.addr}:\n`)
      } else {
        process.stdout.write(`${cell.addr}: ${depAddrs.join(' ')}\n`)
      }
    }
  }

  process.exit(0)
}

